//! Opening books.
//!
//! A book maps positions (by Zobrist hash) to weighted candidate moves. It
//! can be built in memory or from a collection of games in [PDN](crate::pdn):
//!
//! ```text
//! [Event "Two openings"]
//! 1. 32-28 18-23 2. 37-32 12-18 *
//!
//! 1. 33-28 17-21 *
//! ```
//!
//! The first plies of every game are added from the starting position, and
//! moves that several games share gain weight. A binary, memory-mappable
//! format for large books can follow once the book is generated by self-play.

use std::collections::HashMap;
use std::fmt;

use crate::game::IllegalMoveError;
use crate::moves::Move;
use crate::pdn::{self, PdnGame};
use crate::position::Position;

/// A candidate move in the book.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct BookMove {
    /// The move.
    pub mv: Move,
    /// The relative weight when picking among candidates.
    pub weight: u32,
}

/// The error returned when a book game contains an illegal move.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BookError {
    /// The 1-based number of the game in the PDN text.
    pub game: usize,
    /// The 1-based line of the move in the PDN text.
    pub line: usize,
    /// The underlying move error.
    pub error: IllegalMoveError,
}

impl fmt::Display for BookError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "game {}, line {}: {}", self.game, self.line, self.error)
    }
}

impl std::error::Error for BookError {}

/// An in-memory opening book.
#[derive(Clone, Debug, Default)]
pub struct OpeningBook {
    entries: HashMap<u64, Vec<BookMove>>,
}

impl OpeningBook {
    /// An empty book.
    pub fn new() -> Self {
        Self::default()
    }

    /// Plies of each game that go into a book unless told otherwise: the
    /// first ten moves of each side.
    pub const DEFAULT_PLIES: usize = 20;

    /// Builds a book from the first `plies` moves of each game in the PDN
    /// `text`. Games of other variants (a `GameType` other than 20) and
    /// games that start from another position (a `FEN` tag) are skipped.
    pub fn from_pdn(text: &str, plies: usize) -> Result<Self, BookError> {
        let mut book = Self::new();
        for (index, pdn) in pdn::read_games(text).iter().enumerate() {
            if !opens_from_start(pdn) {
                continue;
            }
            // A plain position is enough: `parse_move` only returns legal
            // moves, and the book needs no history or draw counters.
            let mut pos = Position::initial();
            for (text, line) in pdn.moves.iter().take(plies) {
                let mv = pos.parse_move(text).map_err(|error| BookError {
                    game: index + 1,
                    line: *line,
                    error: error.into(),
                })?;
                book.add(&pos, mv, 1);
                pos = pos.after(mv);
            }
        }
        Ok(book)
    }

    /// Adds `weight` to `mv` in `pos`, inserting it if needed.
    pub fn add(&mut self, pos: &Position, mv: Move, weight: u32) {
        let moves = self.entries.entry(pos.hash()).or_default();
        match moves.iter_mut().find(|entry| entry.mv == mv) {
            Some(entry) => entry.weight = entry.weight.saturating_add(weight),
            None => moves.push(BookMove { mv, weight }),
        }
    }

    /// The candidate moves for `pos`, heaviest first.
    pub fn moves(&self, pos: &Position) -> Vec<BookMove> {
        let Some(entries) = self.entries.get(&pos.hash()) else {
            return Vec::new();
        };
        // Guard against hash collisions with positions not in the book.
        let legal = pos.legal_moves();

        let mut moves: Vec<BookMove> = Vec::with_capacity(entries.len());
        for entry in entries {
            if legal.contains(&entry.mv) {
                moves.push(*entry);
            }
        }

        moves.sort_by_key(|entry| std::cmp::Reverse(entry.weight));
        moves
    }

    /// Picks a book move for `pos` with probability proportional to its
    /// weight. `seed` drives the choice, so equal seeds give equal picks.
    pub fn pick(&self, pos: &Position, seed: u64) -> Option<Move> {
        let moves = self.moves(pos);
        let total: u64 = moves.iter().map(|entry| u64::from(entry.weight)).sum();
        if total == 0 {
            return None;
        }
        // One round of splitmix64 turns any seed into a well-spread value.
        let mut z = seed.wrapping_add(0x9E37_79B9_7F4A_7C15);
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        let mut target = (z ^ (z >> 31)) % total;
        moves.into_iter().find_map(|entry| {
            let weight = u64::from(entry.weight);
            if target < weight {
                Some(entry.mv)
            } else {
                target -= weight;
                None
            }
        })
    }

    /// The number of positions in the book.
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// Whether the book is empty.
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }
}

/// Whether `game` is international draughts from the starting position.
fn opens_from_start(game: &PdnGame) -> bool {
    // `GameType` is the variant number, optionally followed by details.
    let international = game
        .tag("GameType")
        .is_none_or(|kind| kind.split(',').next().map(str::trim) == Some("20"));
    let from_start = game.tag("FEN").is_none_or(|fen| {
        Position::from_fen(fen).is_ok_and(|position| position == Position::initial())
    });
    international && from_start
}

#[cfg(test)]
mod tests {
    use super::*;

    const GAMES: &str = r#"
        [Event "two openings sharing the first move"]
        1. 32-28 18-23 2. 37-32 *
        1. 32-28 17-21 {the second} *
        [GameType "20"]
        1. 33-28 *
        [GameType "21"]
        1. 22-18 *
        [FEN "B:W31-50:B1-20"]
        1... 19-23 *
    "#;

    #[test]
    fn weights_accumulate() {
        let book = OpeningBook::from_pdn(GAMES, OpeningBook::DEFAULT_PLIES).unwrap();
        let root = book.moves(&Position::initial());
        let moves: Vec<_> = root.iter().map(|e| (e.mv.to_string(), e.weight)).collect();
        assert_eq!(moves, [("32-28".to_owned(), 2), ("33-28".to_owned(), 1)]);
        assert_eq!(book.len(), 3);
    }

    #[test]
    fn pick_is_deterministic_and_legal() {
        let book = OpeningBook::from_pdn(GAMES, OpeningBook::DEFAULT_PLIES).unwrap();
        let pos = Position::initial();
        for seed in 0..32 {
            let mv = book.pick(&pos, seed).unwrap();
            assert_eq!(book.pick(&pos, seed), Some(mv));
            assert!(pos.legal_moves().contains(&mv));
        }
        assert!(
            book.pick(&pos.after(pos.parse_move("31-26").unwrap()), 0)
                .is_none()
        );
    }

    #[test]
    fn games_are_cut_after_the_plies() {
        let book = OpeningBook::from_pdn(GAMES, 1).unwrap();
        assert_eq!(book.len(), 1);
    }

    #[test]
    fn illegal_moves_are_reported() {
        let err = OpeningBook::from_pdn("1. 32-28 *\n\n1. 32-28\n32-28 *", 20).unwrap_err();
        assert_eq!((err.game, err.line), (2, 4));
        assert!(err.to_string().starts_with("game 2, line 4: "), "{err}");
    }
}
